/**
 * C2 view-layer types.
 *
 * These MIRROR docs/CONTRACTS.md v0 (status: PROPOSED, not locked). They live in
 * C2's own namespace because `src/shared/**` is H-owned. When H locks the
 * contract and publishes shared types, replace these with re-exports from
 * `src/shared` and delete the duplicates. Do not add fields here that are not in
 * the contract without a CR — UI-only derived fields belong in `view.ts`.
 */

export type Hex = `0x${string}`;
export type Address = `0x${string}`;

/** bytes32, server generated. Never generated by the frontend. */
export type VentureId = Hex;

export const SEPOLIA_CHAIN_ID = 11155111 as const;
export const WHITECHAIN_CHAIN_ID = 1874 as const;
/** ENSIP-11: 0x80000000 | 1874 */
export const WHITECHAIN_ENS_COIN_TYPE = 2147485522 as const;

/** CONTRACTS v0 read status enum. */
export type ReadStatus = "UNKNOWN" | "PENDING" | "VERIFIED" | "FAILED";

/** CONTRACTS v0 payment status enum. */
export type PaymentStatus = "AWAITING_APPROVALS" | "READY" | "EXECUTED" | "FAILED";

/** MASTER §3: exact evidence labels. */
export type EvidenceLabel = "HUMAN_VERIFIED" | "SIGNED" | "CHAIN_VERIFIED" | "SELF_REPORTED";

/** MASTER §11 claim classes. Every rendered fact resolves to one of these. */
export type ClaimClass =
  | "VERIFIED_ON_CHAIN"
  | "VERIFIED_OFF_CHAIN"
  | "TESTED_IN_SIMULATOR"
  | "IMPLEMENTED_NOT_TESTED"
  | "MOCK_ONLY"
  | "BLOCKED"
  | "CUT";

/** Where a piece of data came from. `DEV_MOCK` must always be rendered visibly. */
export type DataSource = "DEV_MOCK" | "API" | "CHAIN";

export type FounderSeat = {
  ventureId: VentureId;
  wallet: Address;
  founderSubname: string;
  worldProofStatus: ReadStatus;
  onchainSeatStatus: ReadStatus;
  attestationTxHash?: Hex;
};

export type AgreementSignature = {
  signer: Address;
  signature: Hex;
  signedAt: string;
  /** version the signature was made over — must equal the agreement's version to count */
  version: number;
  docHash: Hex;
};

export type Agreement = {
  ventureId: VentureId;
  agreementId: string;
  version: number;
  /** Private. Only shown to founders of the venture, never on the public page. */
  canonicalJson: string;
  docHash: Hex;
  nonce: string;
  expiry: string;
  signatures: AgreementSignature[];
};

export type Treasury = {
  ventureId: VentureId;
  safeAddress: Address;
  chainId: typeof WHITECHAIN_CHAIN_ID;
  ownerAddresses: Address[];
  threshold: number;
  guardAddress: Address;
  registryAddress: Address;
  verificationStatus: ReadStatus;
  deploymentTxHash: Hex;
};

export type Payment = {
  paymentId: string;
  ventureId: VentureId;
  safeTxHash: Hex;
  recipient: Address;
  tokenAddress: Address;
  /** raw token units as a decimal string (never a float) */
  amountRaw: string;
  reason: string;
  signerWallets: Address[];
  status: PaymentStatus;
  executedTxHash?: Hex;
};

export type EvidenceKind =
  | "VENTURE_CREATED"
  | "ENS_REGISTERED"
  | "FOUNDER_VERIFIED"
  | "SEAT_ATTESTED"
  | "DUPLICATE_REFUSED"
  | "AGREEMENT_VERSION"
  | "AGREEMENT_SIGNED"
  | "SAFE_DEPLOYED"
  | "DEPOSIT"
  | "PAYMENT_PROPOSED"
  | "PAYMENT_APPROVED"
  | "REJECTED_ATTEMPT"
  | "PAYMENT_EXECUTED";

export type Evidence = {
  id: string;
  ventureId: VentureId;
  kind: EvidenceKind;
  label: EvidenceLabel;
  status: ReadStatus;
  chainId?: number;
  txHash?: Hex;
  blockNumber?: number;
  confirmedAt?: string;
  source: DataSource;
};

/** Contract v0 `GET /api/identity/ventures/:id` — "founder seat + ENS + verification summaries". */
export type VentureDetail = {
  ventureId: VentureId;
  slug: string;
  displayName: string;
  ensName: string;
  ensStatus: ReadStatus;
  createdAt: string;
  seats: FounderSeat[];
  /** Single-use invite link material. Only returned to Founder A. Shape TBD by C1. */
  invite?: { code: string; used: boolean };
  agreement?: Agreement;
  source: DataSource;
};

/** Contract v0 `GET /api/treasury/ventures/:id` — "chain readback + pending payments". */
export type TreasuryState = {
  treasury?: Treasury;
  /** raw USDT balance string from chain readback */
  balanceRaw?: string;
  tokenDecimals?: number;
  payments: Payment[];
  deposits: { from: Address; amountRaw: string; txHash: Hex; status: ReadStatus }[];
  source: DataSource;
};

/**
 * Contract v0 `GET /api/identity/public/:ensName` — OFFCHAIN human and agreement
 * evidence only. No authoritative treasury claims, no PII, no full nullifier.
 */
export type PublicOffchainEvidence = {
  ensName: string;
  ventureId: VentureId;
  humansVerified: number;
  founders: { founderSubname: string; worldProofStatus: ReadStatus; verifiedAt?: string }[];
  agreement?: { version: number; docHash: Hex; signaturesForCurrentVersion: number; requiredSignatures: number };
  evidence: Evidence[];
  source: DataSource;
};

/**
 * NOT IN CONTRACT v0 — needed by the funder list (FR-6). Proposed as CR-C2-001
 * (`GET /api/identity/ventures` public summaries, founder-consented). Until
 * accepted, only the DEV MOCK adapter implements it.
 */
export type VentureSummary = {
  ventureId: VentureId;
  displayName: string;
  ensName: string;
  humansVerified: number;
  termsSigned: boolean;
  treasuryActive: boolean;
  funded: boolean;
  source: DataSource;
};

export type AgreementFields = {
  contributions: string;
  roles: string;
  ownershipSplit: string;
  vestingIntent: string;
  decisionRule: string;
  effectiveDate: string;
};
